class AppErrorBoundary extends React.Component {
 constructor(props){super(props);this.state={error:null}}
 static getDerivedStateFromError(error){return {error}}
 componentDidCatch(error){console.error('PIT PRÊMIOS render error:',error)}
 render(){if(this.state.error)return <div style={{minHeight:'100vh',background:'#07120e',color:'#fff',padding:'30px 20px',fontFamily:'system-ui'}}><h2>O PIT PRÊMIOS encontrou um erro</h2><p style={{color:'#9de66f'}}>Esta mensagem ajuda a identificar o problema de inicialização.</p><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere',background:'#102219',padding:'15px',borderRadius:'12px'}}>{String(this.state.error?.message||this.state.error)}</pre><button onClick={()=>location.reload()} style={{padding:'12px 18px',borderRadius:'10px'}}>Recarregar</button></div>;return this.props.children}
}
createRoot(document.getElementById('root')).render(<AppErrorBoundary><App/></AppErrorBoundary>);
